{
  "segment": "past_behavior",
  "learning_goals": [
    "Understand the founder's past experience with similar problems",
    "Identify the founder's current workarounds for the problem",
    "Determine what the founder already spends time or money on"
  ],
  "questions": [
    {
      "question": "What was the problem you faced last time that required a solution?",
      "why": "To understand the founder's experience with similar problems."
    },
    {
      "question": "How do you currently handle the problem you faced last time?",
      "why": "To identify the founder's current workarounds for the problem."
    },
    {
      "question": "What do you already spend time or money on to address the problem?",
      "why": "To determine what the founder already spends time or money on to address the problem."
    },
    {
      "question": "What was the outcome of the solution you implemented for the problem?",
      "why": "To understand the effectiveness of the founder's current solution."
    },
    {
      "question": "What was the cost or time investment for the solution?",
      "why": "To assess the founder's current resource allocation for the problem."
    },
    {
      "question": "What are the limitations or challenges of the solution?",
      "why": "To identify potential constraints or challenges the founder faces."
    },
    {
      "question": "What is the founder's current approach to solving the problem?",
      "why": "To understand the founder's current strategy for addressing the problem."
    },
    {
      "question": "What is the founder's perception of the problem's severity?",
      "why": "To gauge the founder's perception of the problem's importance."
    },
    {
      "question": "What is the founder's opinion on the effectiveness of the solution?",
      "why": "To evaluate the founder's satisfaction with the current solution."
    },
    {
      "question": "What is the founder's plan for future improvements?",
      "why": "To identify potential future enhancements or solutions."
    },
    {
      "question": "What is the founder's current focus or priority?",
      "why": "To understand the founder's current priorities and focus."
    }
  ],
  "avoid": [
    "Hypothetical or future questions",
    "Questions that require the founder to provide an answer"
  ]
}
